// Hover documentation
// ---------------------------------------------------------------------------

export const DOCS: Record<string, string> = {
  // --- Keywords ---
  'mut': '**`mut`** — Declares a mutable variable. Variables are mutable by default, so `mut` is optional — it documents intent but changes nothing.\n\n```gray\nx i64 = 42          // mutable (default)\nmut x i64 = 42      // identical, explicit\nname = "hello"      // mutable, type inferred\n```',
  'const': '**`const`** — Declares an immutable constant or a named struct/enum type.\n\n```gray\nconst PI f64 = 3.14159\nconst Point struct { x i64; y i64 }\n```',
  'if': '**`if`** — Conditional branch. Branches on a boolean expression.\n\n```gray\nif x > 10 {\n    println("big")\n} otherwise {\n    println("small")\n}\n```',
  'otherwise': '**`otherwise`** — The else branch of an `if` or `when` statement. Identical to `else`.',
  'else': '**`else`** — Alias for `otherwise`. The default branch of an `if` or `when` statement.',
  'when': '**`when`** — Pattern-matching switch. Compares a value against a list of cases. `switch` is an alias.\n\n```gray\nwhen x {\n    is 1 { println("one") }\n    is 2 { println("two") }\n    default { println("other") }\n}\n```',
  'switch': '**`switch`** — Alias for `when`. A file that writes `switch` must also write `case` (not `is`); mixing dialects is `E2088`.',
  'is': '**`is`** — Introduces a match arm inside `when`. `case` is the alias used with `switch`.',
  'case': '**`case`** — Alias for `is`, used inside a `switch` block. Pairs with `switch`; mixing with `when`/`is` is `E2088`.',
  'default': '**`default`** — The fallback arm of a `when` expression.',
  'for': '**`for`** — Range-based loop.\n\n```gray\nfor i in range(0, 10) {\n    println(i)\n}\n```',
  'for_each': '**`for_each`** — Iterates over every element of a collection.\n\n```gray\nfor_each item in items {\n    println(item)\n}\n```',
  'while': '**`while`** — Loop that runs while a condition is true. Alias for `as_long_as`.\n\n```gray\nwhile x > 0 {\n    x--\n}\n```',
  'as_long_as': '**`as_long_as`** — Loop that runs while a condition is true. Identical to `while`.',
  'loop': '**`loop`** — Infinite loop. Use `break` to exit.\n\n```gray\nloop {\n    if done { break }\n}\n```',
  'break': '**`break`** — Exits the innermost loop.',
  'continue': '**`continue`** — Skips to the next iteration of the innermost loop.',
  'return': '**`return`** — Returns a value from a function.\n\n```gray\ndo add(a i64, b i64) -> i64 {\n    return a + b\n}\n```',
  'do': '**`do`** — Declares a function (with or without a return type). `fn` is an alias.\n\n```gray\ndo main() {\n    println("Hello, Grayscale!")\n}\n\ndo add(a i64, b i64) -> i64 {\n    return a + b\n}\n```',
  'fn': '**`fn`** — Alias for `do`. Declares a function. A file picks one spelling; mixing `fn` and `do` is `E2088`.',
  'func': '**`func`** — Function type for references and parameters.\n\n```gray\nconst f func(i64) -> i64 = ()double\n```',
  'struct': '**`struct`** — Declares a user-defined composite type.\n\n```gray\nconst Point struct {\n    x i64\n    y i64\n}\n```',
  'enum': '**`enum`** \u2014 Declares a type with a fixed set of named variants.\n\n```gray\nconst Direction enum {\n    NORTH\n    EAST\n    SOUTH\n    WEST\n}\n```\n\nVariants are referenced as `Direction.NORTH`, or as `.NORTH` where the enum type is known from context.\n\n**Tagged enums** \u2014 variants may carry a positional data payload, which makes the enum a tagged union:\n\n```gray\nconst Shape enum {\n    Circle(f64)\n    Rect(f64, f64)\n    Point\n}\n\nmut s Shape = Shape.Circle(3.14)\n```\n\nDestructure payloads with `when`/`is`:\n\n```gray\nwhen shape {\n    is Shape.Circle(radius) { println(radius) }\n    is Shape.Rect(w, h)     { println("${w}x${h}") }\n    is Shape.Point          { println("point") }\n}\n```\n\nAn enum becomes a tagged union if ANY variant has a payload. Payloads and explicit values (`= 5`) are mutually exclusive per variant. String enums and `#flags` enums cannot have payloads.',
  'import': '**`import`** \u2014 Imports a module.\n\n```gray\nimport @math                 // stdlib module\nimport "./helpers.gray"      // local file\nextern import "stdio.h"       // C header\nimport and use @arrays       // import + using in one statement\n```',
  'using': '**`using`** \u2014 Brings a module\'s members into scope for unqualified access. Valid at file scope or inside a single function.\n\n```gray\nimport @strings\nusing strings\n\ndo main() {\n    println(to_upper("hello"))\n}\n```\n\nAt function scope, only that function gets unqualified access. See also `import and use`.',
  'use': '**`use`** \u2014 Used with `import and use` to import a module and bring its members into scope in one statement.\n\n```gray\nimport and use @strings\n\ndo main() {\n    println(to_upper("hello"))   // unqualified, no separate `using`\n}\n```\n\nEquivalent to `import @strings` followed by `using strings`.',
  'new': '**`new`** — Allocates a zero-initialized struct on the arena and returns a pointer.\n\n```gray\nmut p ^Point = new(Point)\n```',
  'alias': '**`alias`** \u2014 Creates an interchangeable name for an existing type.\n\n```gray\nalias Meters = f64\nalias Vec2 = Point\nalias Names = [string]\nalias Lookup = map[string:i64]\n```\n\n**Rules:**\n- File-scope only \u2014 cannot be declared inside a function.\n- Public by default; prefix with `private` to restrict to the declaring file.\n- Erased at compile time \u2014 `type_of()` returns the underlying type name.\n- Transitive: `alias A = i64` then `alias B = A` resolves `B` to `i64`.\n- Can alias primitives, structs, enums, arrays, maps, and pointers.\n- Cannot alias module-qualified types (`mod.Type`) or the wildcard type (`?`).',
  'private': '**`private`** — Restricts visibility of a function or declaration to the current file.',
  'cast': '**`cast`** — Explicit type conversion.\n\n```gray\nmut n i32 = cast(myInt, i32)\n```',
  'in': '**`in`** — Tests membership in a collection.\n\n```gray\nif 5 in numbers { println("found") }\n```',
  'not_in': '**`not_in`** — Tests non-membership in a collection.\n\n```gray\nif 5 not_in numbers { println("missing") }\n```',
  'range': '**`range`** — Creates an integer range for iteration.\n\n```gray\nfor_each i in range(0, 10) { println(i) }\nfor_each i in range(0, 10, 2) { println(i) }  // step 2\n```',
  'or': '**`or`** — Error-propagation operator or else-if branch. `elif` is the alias for the else-if branch.\n\n```gray\nmut val = risky() or { return }\n\nif x < 0 {\n    println("negative")\n} or x == 0 {\n    println("zero")\n}\n```',
  'elif': '**`elif`** — Alias for the `or` else-if branch. Pairs with `else` (not `otherwise`); mixing `elif`/`or` in one file is `E2088`.',
  'or_return': '**`or_return`** — Returns early if the expression is an Error.',
  'ensure': '**`ensure`** — Deferred cleanup. Runs when the surrounding function exits. `defer` is an alias.\n\n```gray\nensure cleanup()\n```',
  'defer': '**`defer`** — Alias for `ensure`. Runs the given call when the surrounding function exits. Mixing `defer` and `ensure` in one file is `E2088`.',
  'true': '**`true`** — Boolean literal representing the true value.',
  'false': '**`false`** — Boolean literal representing the false value.',
  'nil': '**`nil`** — Represents the absence of a value (null pointer).',
  'bit_and': '**`bit_and`** — Bitwise AND operator.\n\n```gray\nmut result = a bit_and b\n```',
  'bit_or': '**`bit_or`** — Bitwise OR operator.\n\n```gray\nmut result = a bit_or b\n```',
  'bit_xor': '**`bit_xor`** — Bitwise XOR operator.\n\n```gray\nmut result = a bit_xor b\n```',
  'bit_not': '**`bit_not`** — Bitwise NOT (complement) prefix operator.\n\n```gray\nmut result = bit_not a\n```',
  'bit_shift_left': '**`bit_shift_left`** — Left shift operator.\n\n```gray\nmut result = 1 bit_shift_left 3  // 8\n```',
  'bit_shift_right': '**`bit_shift_right`** — Right shift operator.\n\n```gray\nmut result = 16 bit_shift_right 1  // 8\n```',
  'and': '**`and`** \u2014 Part of the combined `import and use` statement.\n\n```gray\nimport and use @arrays\n```\n\nEquivalent to:\n\n```gray\nimport @arrays\nusing arrays\n```\n\nMultiple modules can be combined:\n\n```gray\nimport and use @arrays, @strings\n```',

  // --- Types ---
  'string': '**`string`** — UTF-8 encoded u8 sequence. `len()` returns u8 length; use `char_count()` for character count.\n\n```gray\nmut s string = "hello"\n```',
  'bool': '**`bool`** — Boolean type. Values: `true` or `false`.',
  'char': '**`char`** — A single Unicode codepoint, held as a 32-bit integer (`int32_t` at the C boundary). `cast(c, i64)` yields the numeric codepoint; `char(n)` converts a codepoint to a `char`.\n\n```gray\nmut letter char = \'A\'\nmut cjk char = char(26085)\n```',
  'Error': '**`Error`** — Error type returned from functions that can fail. Create with `error("message")`.',
  'map': '**`map`** — Unordered key-value collection. The `map` keyword is optional: `[string:i64]` and `map[string:i64]` are identical.\n\n```gray\nmut ages [string:i64] = {"alice": 30}\n```',
  'i8': '**`i8`** — 8-bit signed integer. Range: -128 to 127.',
  'i16': '**`i16`** — 16-bit signed integer. Range: -32,768 to 32,767.',
  'i32': '**`i32`** — 32-bit signed integer. Range: -2^31 to 2^31-1.',
  'i64': '**`i64`** — 64-bit signed integer. The default type of integer literals. Overflow-checked at runtime.',
  'i128': '**`i128`** — 128-bit signed integer (struct-based). Construct with `i128(value)`.',
  'i256': '**`i256`** — 256-bit signed integer (struct-based). Construct with `i256(value)`.',
  'u8': '**`u8`** — 8-bit unsigned integer. Range: 0 to 255.',
  'u16': '**`u16`** — 16-bit unsigned integer. Range: 0 to 65,535.',
  'u32': '**`u32`** — 32-bit unsigned integer. Range: 0 to 2^32-1.',
  'u64': '**`u64`** — 64-bit unsigned integer. Range: 0 to 2^64-1. Overflow-checked at runtime.',
  'u128': '**`u128`** — 128-bit unsigned integer (struct-based). Construct with `u128(value)`.',
  'u256': '**`u256`** — 256-bit unsigned integer (struct-based). Construct with `u256(value)`.',
  'SourceLocation': '**`SourceLocation`** — Compiler-provided struct returned by `here()`. Fields: `file string`, `line i64`, `column i64`. Always reserved; no import needed.',
  'f32': '**`f32`** — 32-bit IEEE 754 single-precision floating-point.',
  'f64': '**`f64`** — 64-bit IEEE 754 double-precision floating-point. The default type of floating-point literals.',

  // --- Builtins ---
  'println': '**`println(value)`** — Prints a value followed by a newline. Accepts any type.',
  'print': '**`print(value)`** — Prints a value without a trailing newline. Accepts any type.',
  'eprintln': '**`eprintln(value)`** — Prints a value to stderr with a newline.',
  'eprint': '**`eprint(value)`** — Prints a value to stderr without a newline.',
  'flush': '**`flush()`** — Flushes buffered stdout so partial-line output (prompts, progress indicators) appears immediately, even when stdout is a pipe or file.\n\n```gray\nprint("working")\nflush()\n```',
  'input': '**`input() -> string`** — Reads a line from stdin and returns it as a string.',
  'len': '**`len(collection) -> i64`** — Returns the length of an array, map, or string (u8 length for strings).',
  'type_of': '**`type_of(value) -> string`** — Returns the Grayscale type name as a string (e.g. `"i64"`, `"string"`).',
  'size_of': '**`size_of(Type) -> i64`** — Returns the size of a type in bytes.',
  'fields': '**`fields(instance) -> [string]`** \u2014 Returns the field names of a struct as an array of strings, in declaration order.\n\nAccepts struct instances and pointers to structs.\n\n```gray\nconst Point struct {\n    x i64\n    y i64\n}\n\nmut p = Point{x: 1, y: 2}\nprintln(fields(p))   // {"x", "y"}\n```',
  'here': '**`here() -> SourceLocation`** — Returns the call site’s source location: `file` (string), `line` (i64), `column` (i64). No import required.\n\n```gray\nmut loc = here()\nprintln("${loc.file}:${loc.line}")\n```',
  'copy': '**`copy(value) -> T`** — Creates a deep copy of any value.',
  'ref': '**`ref(variable) -> T`** — Creates a transparent reference (alias) to a variable.',
  'addr': '**`addr(variable) -> ^T`** — Returns the memory address of a variable as a pointer.',
  'raw': '**`raw(variable) -> ^T`** \u2014 Returns an unchecked pointer to a variable.\n\nLike `addr()`, but skips nil-check panics and const-source write protection. Unsafe \u2014 the compiler will not stop you from writing through it.\n\n```gray\nmut x i64 = 42\nmut p ^i64 = raw(x)\n```',
  'error': '**`error(code ErrorCode, message string = "") -> Error`** — Creates an Error value carrying an `ErrorCode` and an optional message.\n\n```gray\nreturn error(.NotFound, "missing")\n```',
  'assert': '**`assert(condition bool, message string = "")`** — Panics with P0075 if condition is false. Message is optional.',
  'panic': '**`panic(message string)`** — Terminates the program immediately with an error message.',
  'exit': '**`exit(code i64)`** — Exits the program with the given status code.',
  'system': '**`system(command string) -> i64`** \u2014 Runs a shell command and returns its exit code.\n\nReturns `-1` if the command was killed by a signal.\n\n```gray\nmut code i64 = system("ls -la")\n```',
  'to_char': '**`to_char(s string, index i64) -> char`** — Returns the Unicode codepoint at character position `index`.',
  'char_count': '**`char_count(s string) -> i64`** — Returns the number of Unicode characters (not bytes) in a string.',
  'c_string': '**`c_string(ptr ^u8) -> string`** — Converts a C `char*` pointer to a Grayscale string (C interop).',
  'embed': '**`embed(path string) -> string`** — Reads a file at compile time and bakes its contents into the binary.',
  'sleep_s': '**`sleep_s(seconds i64)`** — Sleeps for the given number of seconds.',
  'sleep_ms': '**`sleep_ms(ms i64)`** — Sleeps for the given number of milliseconds.',
  'sleep_ns': '**`sleep_ns(ns i64)`** — Sleeps for the given number of nanoseconds.',

  // --- C interop ---
  'extern': '**`extern`** \u2014 C interop. Import a C header with `extern import`, then call into it through the `extern.` prefix:\n\n```gray\nextern import "stdio.h"           // system header \u2192 #include <stdio.h>\nextern import "./mylib.h"         // local header  \u2192 #include "./mylib.h"\nextern import "stdio.h", "stdlib.h"\n\ndo main() {\n    extern.puts("hello from C")\n    extern.printf("value: %d\\n", 42)\n    mut eof i64 = extern.EOF        // constants and macros too\n}\n```\n\nThe `extern.` prefix is required at every C call site. A C call result has no Grayscale type of its own: assign it to a type-annotated variable, pass it to another `extern.` call, or convert it with `c_string()`.\n\n```gray\nmut home string = c_string(extern.getenv("HOME"))\n```\n\n**Cannot be passed to C:** `i128`, `i256`, `u128`, `u256`, arrays, maps, and Grayscale structs.\n\nThe module name `extern` is reserved \u2014 a local `extern.gray` must be imported under an alias.',

  // --- Wildcard types ---
  '?': '**`?`** \u2014 Wildcard type. A placeholder that enables generic-style functions.\n\n```gray\ndo identity(x ?) -> ? {\n    return x\n}\n\nmut a = identity(42)        // ? binds to i64\nmut b = identity("hello")   // ? binds to string\n```\n\nAll `?` placeholders in one signature bind to the **same** concrete type, inferred from the first `?` argument:\n\n```gray\ndo pick_first(a ?, b ?) -> ? { return a }\n\npick_first(1, 2)         // OK\npick_first(1, "hello")   // Error: conflicting bindings for ?\n```\n\nWorks with composite types: `do first(arr [?]) -> ?`.\n\n**`?` is only valid in function parameter and return types.** It is rejected in variable declarations, struct fields, `new(?)`, and named return positions. A `?` return requires at least one `?` parameter to provide the binding.',
  '<?>': '**`<?>`** \u2014 Type parameter. Lets a function parameter accept a struct **type name** rather than a value.\n\n```gray\nconst Point struct {\n    x i64\n    y i64\n}\n\ndo make(T <?>) -> ^? {\n    return new(T)\n}\n\nmut p = make(Point)   // -> ^Point\n```\n\nInside the body, the type parameter is valid in `new(T)`, struct literals `T{x: 1}`, and `size_of(T)`.\n\nThe return type uses `?`: `-> ^?` resolves to a pointer to the type argument, `-> ?` to the type argument itself.\n\n**Restrictions:**\n- Type and value parameters cannot be mixed in one signature (E2087).\n- Only struct type names may be passed \u2014 enums, primitives, and expressions are rejected (E3127, E3128).',

  // --- Attributes ---
  '#doc': '**`#doc("...")`** \u2014 Documentation metadata for functions, structs, enums, and file-scope variables. Consumed by `gray doc`.\n\n```gray\n#doc("Adds two numbers")\ndo add(a i64, b i64) -> i64 {\n    return a + b\n}\n```',
  '#json': '**`#json`** \u2014 Enables JSON serialization for a struct. Required by `json.parse()` and `json.stringify()`.\n\nSupported field types: the sized number types, `string`, `bool`, enums, plus nested `#json` structs. `#json` structs cannot have default field values. A field can serialize under a different key with a trailing tag.\n\n```gray\n#json\nconst Person struct {\n    name string `json:\"Name\"`\n    age i64\n}\n```',
  '#flags': '**`#flags`** \u2014 Marks an enum as a bitflag set. Variant values become powers of 2 instead of auto-incrementing from 0.\n\n```gray\n#flags\nconst Permissions enum {\n    READ      // 1\n    WRITE     // 2\n    EXECUTE   // 4\n}\n```',
  '#error_code': '**`#error_code`** \u2014 Marks a plain integer-backed enum as contributing its variants to the open `ErrorCode` set. Variant names must be unique across the whole set.\n\n```gray\n#error_code\nconst NetError enum {\n    TIMEOUT\n    REFUSED\n}\n```',
  '#strict': '**`#strict`** \u2014 Applied to a `when` block, requires every variant of the matched enum to be handled.\n\n```gray\n#strict\nwhen dir {\n    is .NORTH { }\n    is .EAST  { }\n    is .SOUTH { }\n    is .WEST  { }\n}\n```',
  '#discard': '**`#discard`** \u2014 Marks a function whose return value may safely be ignored by callers.\n\nWithout `#discard`, calling a non-void function as a bare statement produces **E5011** (return value not used). With it, callers may drop the result.\n\n```gray\n#discard\ndo log(msg string) -> i64 {\n    println(msg)\n    return 0\n}\n\ndo main() {\n    log("hello")   // no E5011\n}\n```\n\nApplies to plain functions and struct functions. Cannot be applied to structs, enums, or variables (E2002), nor to void functions (E5042).',
  '#deprecated': '**`#deprecated`** / **`#deprecated("...")`** \u2014 Marks a function, struct, or enum as deprecated. Every reference to the item warns with **W3007**; the optional string names a replacement.\n\n```gray\n#deprecated("use parse_v2 instead")\ndo parse(s string) -> i64 {\n    return 0\n}\n```\n\nDeclaration-only \u2014 not yet supported on struct functions (E2002).',
  '#test': '**`#test`** \u2014 Marks a function as a test. Run by `gray test` and stripped from normal builds.\n\n```gray\n#test\ndo adds_two_numbers() {\n    assert(add(2, 2) == 4)\n}\n```\n\nCannot be applied to `main` (it is the program entry point). Attributes may also be grouped on one line: `#[test]`, `#[doc("x"), json]`.',

  // --- Stdlib modules ---
  'arrays': '**`@arrays`** — Array utilities: `append`, `remove`, `contains`, `reverse`, `sort`, `slice`, `flatten`, `map`, `filter`, `reduce`, `any`, `all`, etc.',
  'strings': '**`@strings`** — String manipulation: `split`, `join`, `trim`, `contains`, `starts_with`, `ends_with`, `replace`, `to_upper`, `to_lower`, `to_snake_case`, `char_at`, `to_chars`, `from_chars`, and the `Builder` type (`builder`, `builder_append`, `build`).',
  'chars': '**`@chars`** — Scalar `char` operations: `to_upper`, `to_lower` (ASCII case folding). Character classification predicates live in `@strings`.',
  'maps': '**`@maps`** — Map utilities: `get_keys`, `get_values`, `has_key`, `remove_key`, `merge`, `is_equal`, etc.',
  'math': '**`@math`** — Math functions: `abs`, `sqrt`, `pow`, `log`, `sin`, `cos`, `tan`, `ceil`, `floor`, `round`, `min`, `max`, `clamp`, `lerp`, etc.',
  'time': '**`@time`** — Time utilities: `now`, `format`, `parse`, `to_iso`, `date`, `add_days`, `humanize`, `tick`, `elapsed_ms`, `diff`, etc.',
  'random': '**`@random`** — Random number generation: `rand_int`, `rand_float`, `seed`, `choice`, `shuffle`, etc.',
  'json': '**`@json`** — JSON encoding/decoding: `parse`, `stringify`, `encode`, `decode`, `is_valid`, `pretty_print`.',
  'io': '**`@io`** — File and directory I/O: `read_file`, `write_file`, `read_lines`, `file_exists`, `walk`, `glob`, `path_join`, etc.',
  'os': '**`@os`** — OS interaction: `get_env`, `set_env`, `args`, `current_dir`, `exec`, `pid`, `arch`, etc.',
  'http': '**`@http`** — HTTP client: `get`, `post`, `put`, `patch`, `delete`, `head` with custom headers.',
  'crypto': '**`@crypto`** — Cryptographic functions: `sha256`, `md5`, `random_hex`.',
  'encoding': '**`@encoding`** — Base64, hex, and URL encoding/decoding, `[u8]` conversions (`from_string`, `to_string`, `to_hex`, `from_base64`), and HTML/shell escaping.',
  'uuid': '**`@uuid`** — UUID generation: `generate`, `generate_random`, `generate_time_ordered`, `parse`, `is_valid`, etc.',
  'binary': '**`@binary`** — Encode and decode sized integers and floats to and from `[u8]`, in little-endian (`_le`) and big-endian (`_be`) forms.',
  'sqlite': '**`@sqlite`** — SQLite database access: `open`, `close`, `exec`, `query`.',
  'server': '**`@server`** — HTTP server: `add_router`, `add_route`, `listen`, `cors`, response builders.',
  'regex': '**`@regex`** — Regular expressions: `is_match`, `find`, `find_all`, `replace`, `split`.',
  'csv': '**`@csv`** — CSV parsing and writing: `parse`, `encode`, `read_file`, `write_file`, `headers`.',
  'net': '**`@net`** — TCP sockets and DNS: `connect`, `listen`, `accept`, `send`, `receive`, `resolve`.',
  'threads': '**`@threads`** — Thread lifecycle: `spawn`, `join`, `detach`, `is_alive`, `sleep`, `yield`.',
  'sync': '**`@sync`** — Synchronization: `mutex`, `lock`, `unlock`, `try_lock`, `destroy`.',
  'channels': '**`@channels`** — Message passing: `open`, `send`, `receive`, `close`, `try_send`, `try_receive`.',
  'mem': '**`@mem`** — Arena memory: `arena`, `destroy`, `reset`, `init`, `alloc`, `make`, `raw_copy`.',
  'atomic': '**`@atomic`** — Lock-free atomics: `load`, `store`, `add`, `cas`, `spinlock`, `fence`.',
  'fmt': '**`@fmt`** — Formatted output: `printf`, `sprintf`, `pad_left`, `pad_right`, `int_to_hex`, `float_fixed`.',
  'strconv': '**`@strconv`** — String conversions: `to_int`, `to_float`, `to_bool`, `from_int`, `is_numeric`, `is_integer`.',
  'runtime': '**`@runtime`** — Read-only introspection into the compiler-managed arenas, execution state, and build info: `arena_usage`, `heap_usage`, `peak_usage`, `alloc_count`, `call_depth`, `version`, `uptime`, etc.',
};
